// What spec-0.4.0 changes for a verifier library (SPEC 10.1 "What verifier libraries of
// spec-0.4.0 must do", SPEC 14 spec-0.4.0), through the public API. The vectors are run by
// test/conformance.test.mjs; these tests pin the library's result shape and API additions, and
// compare the library with the reference tool on the probes in
// test/fixtures/oracle-probes-0.4.0.jsonl.gz (generated by tools/oracle-diff/probes_0_4.py, which
// runs spec/tools/canon.py as a black box), where SPEC.md leaves an order or a case open.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { gunzipSync } from 'node:zlib';
import * as lib from '../dist/esm/index.js';
import { makeRunner } from '../tools/vector-runner.mjs';
import { root, vector, utf8, text } from './helpers.mjs';

const { canonicalize, verify, checkEnvelope, keysFromResponse, functionHash, resolvedUnit, sliceId, membersHash, sliceEntry, ERROR_CODES, DatumeshError } = lib;
const keysOf = (v) => Object.entries(v.keys).map(([h, e]) => keysFromResponse(h, e.https.status, e.https.body));
const sha = (s) => createHash('sha256').update(s).digest('hex');
const codeOf = (f) => {
  try {
    f();
    return 'OK';
  } catch (e) {
    if (e instanceof DatumeshError) return e.code;
    throw e;
  }
};

test('ERROR_CODES: E_SLICE_MEMBER after E_INPUT_UNDECLARED, E_INPUT_SUPERSEDED after E_EVAL_UNAVAILABLE (SPEC 10.2 order)', () => {
  const at = (c) => ERROR_CODES.indexOf(c);
  assert.equal(ERROR_CODES[at('E_SLICE_MEMBER') - 1], 'E_INPUT_UNDECLARED');
  assert.equal(ERROR_CODES[at('E_SLICE_MEMBER') + 1], 'E_VALUE_MISMATCH');
  assert.equal(ERROR_CODES[at('E_INPUT_SUPERSEDED') - 1], 'E_EVAL_UNAVAILABLE');
  assert.equal(ERROR_CODES[at('E_INPUT_SUPERSEDED') + 1], 'E_BLOB_MISMATCH');
  assert.equal(ERROR_CODES.length, 44);
});

test('the library agrees with the reference tool on every spec-0.4.0 probe', async () => {
  const lines = gunzipSync(readFileSync(join(root, 'test', 'fixtures', 'oracle-probes-0.4.0.jsonl.gz'))).toString('utf8').trim().split('\n').map((l) => JSON.parse(l));
  assert.ok(lines.length >= 170, `${lines.length} probes`);
  const run = makeRunner(lib, (b) => sha(b));
  const diffs = [];
  for (const { vector: v, oracle } of lines) {
    const got = (await run(v)).error ?? 'success';
    if (got !== oracle) diffs.push(`${v.id}: reference ${oracle}, library ${got}`);
  }
  assert.deepEqual(diffs, []);
});

test('10.1 step 3: slice entries in inputs (form, order after receipt hashes, one entry each); signed level only needs that', () => {
  const v = vector('receipt/slice-signed-only');
  const r = verify(v.input, keysOf(v));
  assert.deepEqual([r.ok, r.code, r.level, r.hash], [true, 'OK', 'signed', v.sha256]);
  const R = JSON.parse(v.input);
  const H = 'a'.repeat(64);
  const entry = `slice:${'b'.repeat(64)}:${'c'.repeat(64)}`;
  assert.equal(entry.length, 135);
  // canonicalize checks steps 2-4 only, so no signature is needed to see step 3's codes.
  const c = (inputs) => codeOf(() => canonicalize({ ...R, inputs }, 'receipt'));
  assert.equal(c([H, entry]), 'OK');
  assert.equal(c([entry, H]), 'E_CANON_SET');
  assert.equal(c([entry, entry]), 'E_CANON_SET');
  for (const bad of [entry.slice(0, -1), `${entry}0`, entry.replace('slice:', 'Slice:'), entry.replace('slice:', 'slice'), entry.toUpperCase(), `slice:${'b'.repeat(64)}${'c'.repeat(64)}`, `slice:${'b'.repeat(64)}:${'C'.repeat(64)}`, `slice:${'b'.repeat(64)}:${'c'.repeat(63)}:`, `${H}:${H}`]) {
    assert.equal(c([bad]), 'E_CANON_HEX', bad);
  }
  const many = (n) => Array.from({ length: n }, (_, i) => `slice:${i.toString(16).padStart(64, '0')}:${'c'.repeat(64)}`);
  assert.equal(c(many(4096)), 'OK');
  assert.equal(c(many(4097)), 'E_CANON_LIMIT');
});

test('slice objects and manifests: canonicalize kinds "slice" and "manifest", sliceId, membersHash, sliceEntry', () => {
  for (const id of ['slice/range', 'slice/unbounded', 'slice/two-open', 'slice/version', 'slice/range-reversed']) {
    const v = vector(id);
    assert.equal(text(canonicalize(v.input, 'slice')), v.canonical, id);
    assert.equal(sliceId(v.input), v.slice_id, id);
    assert.equal(sliceId(JSON.parse(v.input)), v.slice_id, id);
    assert.equal(sliceId(utf8(v.input)), v.slice_id, id);
  }
  // An unbounded slice's id is the cell id of the cell object with the marker (SPEC 4.4).
  const u = vector('slice/unbounded');
  assert.equal(sliceId(u.input), lib.cellHash(u.input));
  for (const id of ['slice/manifest', 'slice/manifest-empty', 'slice/manifest-version']) {
    const v = vector(id);
    assert.equal(text(canonicalize(v.input, 'manifest')), v.canonical, id);
    const m = JSON.parse(v.input);
    assert.equal(membersHash(m.members), v.members_hash, id);
    assert.equal(sliceEntry(v.input), v.entry, id);
    assert.equal(sliceEntry(m), v.entry, id);
    // Kind inference: a manifest has `members`.
    assert.equal(text(canonicalize(v.input)), v.canonical, id);
  }
  assert.equal(membersHash([]), sha('[]'));
  // A version slice is inferred from `from` / `to`.
  assert.equal(text(canonicalize(vector('slice/version').input)), vector('slice/version').canonical);
  // Members: 64 lowercase hex each, strictly ascending, at most 1,048,576 (SPEC 4.5).
  assert.equal(codeOf(() => membersHash(['A'.repeat(64)])), 'E_CANON_HEX');
  assert.equal(codeOf(() => membersHash(['b'.repeat(64), 'a'.repeat(64)])), 'E_CANON_SET');
  assert.equal(codeOf(() => membersHash('x')), 'E_SCHEMA');
  const big = Array.from({ length: 1048577 }, (_, i) => i.toString(16).padStart(64, '0'));
  assert.equal(codeOf(() => membersHash(big)), 'E_CANON_LIMIT');
  // A slice object is not a manifest and vice versa; a cell without an open argument is no slice.
  assert.equal(codeOf(() => canonicalize(vector('slice/range').input, 'manifest')), 'E_SCHEMA');
  assert.equal(codeOf(() => sliceId(vector('invalid/slice-no-open-argument').input)), 'E_SLICE');
  assert.equal(codeOf(() => sliceEntry(vector('invalid/slice-manifest-duplicate').input)), 'E_CANON_SET');
  // A range object is allowed only in a slice object, not in a cell (SPEC 4.2).
  assert.equal(codeOf(() => canonicalize(vector('slice/range').input, 'cell')), 'E_SCHEMA');
});

test('7: signature.order and argument extent are accepted, hashed, and absent change nothing', () => {
  for (const id of ['function/order', 'function/extent-values', 'function/extent-range']) {
    const v = vector(id);
    assert.equal(functionHash(v.input), v.sha256, id);
  }
  const fx = vector('function/stored-fx-rate');
  const d = JSON.parse(fx.input);
  assert.equal(functionHash(d), fx.sha256);
  const withOrder = { ...d, signature: { ...d.signature, order: ['base', 'date', 'quote'] } };
  assert.notEqual(functionHash(withOrder), fx.sha256);
  // Positional binding order is any permutation, but it lists every argument exactly once.
  assert.equal(codeOf(() => functionHash({ ...d, signature: { ...d.signature, order: ['quote', 'date', 'base'] } })), 'OK');
  assert.equal(codeOf(() => functionHash({ ...d, signature: { ...d.signature, order: ['quote', 'date'] } })), 'E_CANON_SET');
  assert.equal(codeOf(() => functionHash({ ...d, signature: { ...d.signature, order: {} } })), 'E_SCHEMA');
  // resolvedUnit works through a descriptor with order and extent.
  const o = vector('function/order');
  const cell = { args: { base: { type: 'string', value: 'EUR' }, date: { type: 'date', value: '2024-03-15' }, quote: { type: 'string', value: 'USD' } }, fn: 'fx_rate', fn_hash: o.sha256, ns: 'rates.example.org' };
  assert.equal(resolvedUnit(o.input, cell), 'USD/EUR');
});

test('units.md: min, h, d, km and deg are units (spec-0.4.0)', () => {
  const fx = JSON.parse(vector('function/stored-fx-rate').input);
  for (const u of ['min', 'h', 'd', 'km', 'deg']) {
    const desc = { ...fx, signature: { args: {}, returns: { type: 'number', unit: u } } };
    assert.equal(codeOf(() => functionHash(desc)), 'OK', u);
    const cell = { args: {}, fn: 'x', fn_hash: functionHash(desc), ns: 'a.example.org' };
    assert.equal(resolvedUnit(desc, cell), u);
  }
  for (const u of ['Min', 'H', 'D', 'KM', 'Deg', 'hr', 'day', 'degree', '°']) {
    assert.equal(codeOf(() => functionHash({ ...fx, signature: { args: {}, returns: { type: 'number', unit: u } } })), 'E_CANON_UNIT', u);
  }
});

test('10.1 step 7.5 for slice entries: recomputed through manifests and members', () => {
  for (const id of ['receipt/slice-weighted-mean', 'receipt/slice-range', 'receipt/slice-version', 'receipt/slice-empty', 'receipt/slice-mixed-inputs', 'receipt/slice-computed-members', 'receipt/slice-join']) {
    const v = vector(id);
    const r = verify(v.input, keysOf(v), v.recompute);
    assert.deepEqual([r.ok, r.code, r.level, r.path], [true, 'OK', 'recomputed', null], id);
  }
  const v = vector('receipt/slice-weighted-mean');
  const ks = keysOf(v);
  // Manifests may be given as JSON text, bytes or parsed values; members as receipts by hash.
  const asObjects = { ...v.recompute, manifests: Object.fromEntries(Object.entries(v.recompute.manifests).map(([k, m]) => [k, JSON.parse(m)])) };
  assert.equal(verify(v.input, ks, asObjects).level, 'recomputed');
  const asBytes = { ...v.recompute, manifests: Object.fromEntries(Object.entries(v.recompute.manifests).map(([k, m]) => [k, utf8(m)])) };
  assert.equal(verify(v.input, ks, asBytes).level, 'recomputed');
  // A manifest's text is parsed strictly, with the parse codes.
  const [e0] = Object.keys(v.recompute.manifests).sort();
  const dup = { ...v.recompute, manifests: { ...v.recompute.manifests, [e0]: v.recompute.manifests[e0].replace(/^\{/, '{"members": [], ') } };
  assert.equal(verify(v.input, ks, dup).code, 'E_PARSE_DUPLICATE_KEY');
  // Without manifests at all: unavailable.
  const { manifests, ...noManifests } = v.recompute;
  const r = verify(v.input, ks, noManifests);
  assert.deepEqual([r.ok, r.code, r.path], [false, 'E_INPUT_UNAVAILABLE', '$.inputs']);
  // Without a value, after 7.5 passes: E_EVAL_UNAVAILABLE as before.
  const { value, ...noValue } = v.recompute;
  assert.equal(verify(v.input, ks, noValue).code, 'E_EVAL_UNAVAILABLE');
  for (const id of ['invalid/receipt-slice-member-outside', 'invalid/receipt-slice-member-duplicate-cell', 'invalid/receipt-slice-version-outside']) {
    const b = vector(id);
    const x = verify(b.input, keysOf(b), b.recompute);
    assert.deepEqual([x.ok, x.code, x.level, x.path], [false, 'E_SLICE_MEMBER', null, '$.inputs'], id);
  }
});

test('10.1 step 7.6: E_INPUT_SUPERSEDED is success at level signed at $.inputs, only with a lineage', () => {
  for (const id of ['receipt/slice-superseded', 'receipt/slice-superseded-member']) {
    const v = vector(id);
    const ks = keysOf(v);
    const r = verify(v.input, ks, v.recompute);
    assert.deepEqual({ ok: r.ok, code: r.code, level: r.level, hash: r.hash, path: r.path, blobChecked: r.blobChecked }, { ok: true, code: 'E_INPUT_SUPERSEDED', level: 'signed', hash: v.sha256, path: '$.inputs', blobChecked: false }, id);
    assert.match(r.detail, /supersed/);
    // Without the lineage: an ordinary value mismatch.
    const { lineage, ...noLineage } = v.recompute;
    assert.equal(verify(v.input, ks, noLineage).code, 'E_VALUE_MISMATCH', id);
    // With the receipt's own value: recomputed, whatever the lineage says.
    const R = JSON.parse(v.input);
    const same = verify(v.input, ks, { ...v.recompute, value: { type: R.type, value: R.value } });
    assert.deepEqual([same.code, same.level], ['OK', 'recomputed'], id);
    // Without a value: evaluation unavailable, lineage or not.
    const { value, ...noValue } = v.recompute;
    assert.equal(verify(v.input, ks, noValue).code, 'E_EVAL_UNAVAILABLE', id);
    // Step 7.7 after it as after E_EVAL_UNAVAILABLE: content for a non-blob value is E_SCHEMA.
    assert.equal(verify(v.input, ks, v.recompute, new Uint8Array(1)).code, 'E_SCHEMA', id);
  }
  // Lineage must be an array of strings; manifests an object (programmer errors).
  const v = vector('receipt/slice-superseded');
  assert.throws(() => verify(v.input, keysOf(v), { ...v.recompute, lineage: 'x' }), TypeError);
  assert.throws(() => verify(v.input, keysOf(v), { ...v.recompute, lineage: [1] }), TypeError);
  assert.throws(() => verify(v.input, keysOf(v), { ...v.recompute, manifests: [] }), TypeError);
});

test('5.5: not_covered may carry a formula evaluation fault; the result exposes it', () => {
  const v = vector('envelope/not-covered-fault');
  const r = checkEnvelope(v.status, v.input, [], v.request);
  assert.deepEqual([r.ok, r.code, r.outcome, r.fault], [true, 'OK', 'not_covered', 'E_FORMULA_DIV_ZERO']);
  for (const f of ['E_FORMULA_DIV_ZERO', 'E_FORMULA_DOMAIN', 'E_FORMULA_RANGE', 'E_FORMULA_EMPTY', 'E_FORMULA_ABSENT', 'E_FORMULA_FUTURE']) {
    const x = checkEnvelope(404, JSON.stringify({ outcome: 'not_covered', fault: f }), [], v.request);
    assert.deepEqual([x.code, x.fault], ['OK', f], f);
  }
  for (const f of ['E_FORMULA_BUDGET', 'E_FORMULA_CYCLE', 'E_EVAL_UNAVAILABLE', 'e_formula_div_zero', '', 5, null, ['E_FORMULA_DOMAIN']]) {
    const x = checkEnvelope(404, JSON.stringify({ outcome: 'not_covered', fault: f }), [], v.request);
    assert.deepEqual([x.ok, x.code, x.path, x.fault], [false, 'E_ENVELOPE', '$.fault', null], JSON.stringify(f));
  }
  const plain = checkEnvelope(404, '{"outcome":"not_covered"}', [], v.request);
  assert.deepEqual([plain.code, plain.fault], ['OK', null]);
  for (const outcome of ['unlicensed', 'ok', 'error']) {
    assert.equal(checkEnvelope(403, JSON.stringify({ outcome, fault: 'E_FORMULA_DIV_ZERO' }), [], v.request).code, 'E_ENVELOPE', outcome);
  }
  // An error envelope may carry the new verification codes too.
  for (const c of ['E_SLICE_MEMBER', 'E_INPUT_SUPERSEDED']) assert.equal(checkEnvelope(500, JSON.stringify({ outcome: 'error', error: c }), [], v.request).code, 'OK', c);
  const served = vector('envelope/served-ok');
  assert.equal(checkEnvelope(served.status, served.input, keysOf(served), served.request).fault, null);
});
